#
# Lands the sweep's reports on the bot-maintained evals branch and keeps one open
# PR for them. Called by the `publish` job of eval_crate.yml, which is the single
# writer to that branch -- so there is no push race to retry around.
#
# Reads: BRANCH, DEFAULT_BRANCH, SOURCE_SHA, GH_TOKEN.
set -euo pipefail
shopt -s nullglob

: "${BRANCH:?}" "${DEFAULT_BRANCH:?}" "${SOURCE_SHA:?}"

found=(artifacts/eval-crate-*/*-quality-evaluation-report-*.md)
if [ ${#found[@]} -eq 0 ]; then
    echo "::warning::no reports were produced; nothing to publish"
    exit 0
fi

git config user.name "github-actions[bot]"
git config user.email "41898282+github-actions[bot]@users.noreply.github.com"

# Branch off the DEFAULT branch, not whatever ref dispatched this run: a dispatch
# from a feature branch would otherwise create the evals branch there and open a
# PR carrying that branch's commits.
if git fetch origin "$BRANCH:$BRANCH" 2>/dev/null; then
    git checkout "$BRANCH"
    git rebase "origin/$DEFAULT_BRANCH" || {
        echo "::warning::evals branch would not rebase; recreating from $DEFAULT_BRANCH"
        git rebase --abort || true
        git checkout -B "$BRANCH" "origin/$DEFAULT_BRANCH"
    }
else
    git checkout -b "$BRANCH" "origin/$DEFAULT_BRANCH"
fi

mkdir -p reports
landed=()
for report in "${found[@]}"; do
    # `<crate>-quality-evaluation-report-<date>.md`. Strip the whole known middle
    # in ONE pattern rather than peeling the date off separately: the date
    # contains dashes, so `${base%-*}` removes only `-14` and nothing matches
    # afterwards. This form also leaves a dashed crate name intact.
    base=$(basename "$report" .md)
    crate=${base%-quality-evaluation-report-*}
    if [ "$crate" = "$base" ]; then
        echo "::warning::cannot parse a crate out of $report; skipping"
        continue
    fi
    date_part=${base##*-quality-evaluation-report-}
    summary="$(dirname "$report")/$crate-eval-summary-$date_part.json"
    # Committed under the undated name: the evals branch carries the current
    # report per crate and git carries the history, so the weekly sweep does not
    # accumulate a file per run. The dated name exists so the agent's `Write`
    # never has to overwrite a file it has not read.
    cp "$report" "reports/$crate-quality-evaluation-report.md"
    # A missing summary must be visible, not papered over with the previous run's
    # file: remove the committed one so the absence shows.
    rm -f "reports/$crate-eval-summary.json"
    if [ -f "$summary" ]; then
        cp "$summary" "reports/$crate-eval-summary.json"
    else
        echo "::warning::$crate produced no summary; its stale summary was removed"
    fi
    landed+=("$crate")
done

git add -A reports
if git diff --cached --quiet; then
    echo "no report changed; nothing to push"
    exit 0
fi

body=$(for c in "${landed[@]}"; do
    jq -r --arg c "$c" '"- \($c): \(.headline)"' \
        "reports/$c-eval-summary.json" 2>/dev/null || echo "- $c: report refreshed"
done)
git commit -s -m "chore(reports): Refresh crate quality evaluations" \
    -m "$body" \
    -m "Generated by the eval-crate skill from $SOURCE_SHA."
# Single writer, so no retry loop is needed -- but force-with-lease rather than
# force, so an unexpected concurrent writer is not clobbered.
git push --force-with-lease origin "$BRANCH"

# Gate on an OPEN PR: `gh pr view` also succeeds for closed and merged ones,
# which would mean no PR is ever reopened after a merge.
open=$(gh pr list --head "$BRANCH" --state open --json number --jq length)
if [ "$open" -eq 0 ]; then
    gh pr create --base "$DEFAULT_BRANCH" --head "$BRANCH" \
        --title "chore(reports): Refresh crate quality evaluations" \
        --body "Automated \`eval-crate\` output, refreshed by the weekly sweep. Findings are tagged CONFIRMED or PLAUSIBLE by the skill's verification pass; each summary JSON records how many were withdrawn. Advisory -- review the findings, do not merge blindly."
fi
